mapper.select:
select
  date_format(VALUE_DATE,'%Y-%m') yDate,
  sum(W_YIELD) swYield
  from  REP_PROD_INDEX
  where
  VALUE_DATE     >=  #{beforeDate,jdbcType=TIMESTAMP}
  and VALUE_DATE     <=   #{endDate,jdbcType=TIMESTAMP}
  and PROD_ID=#{prodId,jdbcType=VARCHAR}
  group by date_format(VALUE_DATE,'%Y-%m')
